setcps(.1)

// Arrive, breathe, go deeper, rest, then silence
song("arrive@4 breathe@24 deepen@24 rest@8", "once")

// One cycle is one breath: six a minute, easing to five through the deep part
tempomap("0:6 28:6 52:5")

// The tone rises on the in-breath and settles on the out-breath
tone: note("[a2,e3] [f2,c3]").s("sine").attack(3).release(4)
  .gain(bysec("arrive:.1 rest:.1 *:.15"))

// A soft rush of air on each in-breath, while you are still counting
breath: s("pink ~").hpf(200).lpf(600).attack(4).release(5).gain(.05)
  .sections("arrive breathe")

// Waves rolling in, then drawing back
surf: s("surf").slow(2).intensity(.4).gain(env(".2 .28@4 .12", "song"))

// A far-off bell every few breaths, only in the deep part
bell: note("<a4 ~ e4 ~ c5 ~ ~ ~>").s("sine").fm(2).fmh(3.5)
  .decay(5).sustain(0).release(5).room(.8).size(.95).gain(.07)
  .sections("deepen")

setcpm(56/4)

// Kindling, then the tune twice with two endings, a slower pass, humming and embers
song("kindling@4 (glow@8 1.turn@4 2.hum@8)*2 glow'@8 hum@8 embers@8", "once")

// Slowing as the fire burns down
tempomap("0:14 48:14 56:10")

// The fire
fire: s("fire").slow(4).intensity(.3).density(6).gain(env(".18 .24@4 .2", "song"))

// Slow arpeggios: D, Bm, G, A; half speed on the last glow, darker in the embers
guitar: note("<[d3 a3 d4 f#4 a4 f#4 d4 a3] [b2 f#3 b3 d4 f#4 d4 b3 f#3] [g2 d3 g3 b3 d4 b3 g3 d3] [a2 e3 a3 c#4 e4 c#4 a3 e3]>")
  .s("triangle").timbre("soft")
  .attack(.005).decay(.9).sustain(0).release(1.2)
  .lpf(bysec("embers:900 *:1600")).pan(.4).room(.5).gain(.2)
  .exceptSections("kindling").variant(x => x.slow(2))

// A tune hummed by the fire
hum: note("<f#4 d4 d4 c#4>").s("hum").attack(1).release(2).pan(.6).gain(.11)
  .sections("hum glow' embers")

// The clock on the mantel
clock: s("tick*4").lpf(3000).gain(bysec("kindling:.04 embers:.03 *:.05"))

setcpm(40/4)

// A descent, two long delta passes and a deep ending, then silence
song("descend@10 delta@40 delta'@40 deep@20", "once")

// Slowing through the deep ending
tempomap("0:10 90:10 110:8")

// Headphones: a 2 Hz delta beat, below the 3-30 Hz range that shows a warning
drone: note("<c2 c2 ab1 bb1>").slow(2).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.32)

// A dark pad that slowly opens and closes, rising in and fading over the whole piece
pad: note("[c3,g3,eb4]").slow(4).s("sawtooth").unison(4).detune(.3)
  .lpf(sine.range(300, 900).slow(16)).attack(4).release(6)
  .room(.8).size(.95).gain(env("0 .1@6 .04", "song"))

// A floor of brown noise that thickens as you go down
noise: s("brown").slow(8).lpf(400).gain(env(".06 .1@3 .12", "song"))

// Bells far away, an octave lower on the second pass
bells: note("<g4 ~ ~ ~ eb4 ~ ~ ~>").s("sine").fm(1.5).fmh(2)
  .decay(6).sustain(0).release(6).distance(6).gain(.08)
  .sections("delta").variant(x => x.add(-12))

setcpm(30/4)

// A deep, steady blanket of brown noise
blanket: s("brown").slow(8).lpf(600).gain(.25)

// A faint airy layer on top
hush: s("pink").slow(8).hpf(1500).lpf(4000).gain(.02)

// A low hum underneath
hum: note("f1").slow(8).s("hum").gain(.1)

